\begin{equation}\label{eq: condition1}
\liminf_{n\to\infty}\frac{k_n}{\log(n)}>\gamma^{-1}\,,
\end{equation} 
then 
\begin{equation}
\textbf{1}_{\maxset{k_n}{n}}(1)\xrightarrow{n\to\infty}1\, \ \ P\text{-a.s.}
