\label{prop:weak_strong_different_f}
	 Let $F$ be a general distribution function. Then, 
	\begin{enumerate}
	 \item $p_{k,n}^{(F)} \leq p^{(U)}_{k,n}$.

	 \item $p_{k,n}^{(p)} \leq p_{k,n}^{(F)}$ for every $p \in \left\{1-F(x);x\in\mathbb{R}\right\}$. 
	\end{enumerate}

\normalfont	$\text{}$
\begin{enumerate}
 \item  The random variables $X_{ij} \sim F$ can be realized by taking uniform random variables $U_{ij} \sim U$, and then taking the transformation $X_{ij} = F^{-1}(U_{ij})$, where $F^{-1}$ is the pseudo-inverse of $F$. Thus, since $F^{-1}$ is nondecreasing we have $U_{j}^k \succcurlyeq U_{i}^k \Rightarrow X_{j}^k \succcurlyeq X_{i}^k $ and hence
$X_{i}^k \in \maxset{k}{n}^{(F)} \Rightarrow U_{i}^k \in \maxset{k}{n}^{(U)}$. Therefore, $\maxset{k}{n}^{(F)} \subseteq \maxset{k}{n}^{(U)}$ and hence $p_{k,n}^{(F)} \leq p^{(U)}_{k,n}$. 

\item Take $x$ with $p \equiv 1-F(x)$ and define $B_{ij} = \textbf{1}_{\{X_{ij} > x\}}$. Since $B_{ij}$ is a nondecreasing transformation of $X_{ij}$, then $B_{i}^j \in \maxset{k}{n}^{(p)} \Rightarrow X_{i}^j \in \maxset{k}{n}^{(F)}$. As a result, $\maxset{k}{n}^{(p)} \subseteq \maxset{k}{n}^{(F)}$ and hence $p_{k,n}^{(p)} \leq p_{k,n}^{(F)}$. \hfill \vrule height1.3ex width1.2ex depth-0.1ex
\end{enumerate}

For every $k,n\geq1$, there are well-known exact formulas for $p_{k,n}^{(U)}$ (see e.g. \cite{bai2005maxima}):
\begin{enumerate}
\item 
\begin{equation} 
\label{eq: combinatorial formula}
p_{k,n}^{(U)} = \sum_{u=1}^n\binom{n-1}{u-1}\frac{(-1)^{u-1}}{u^k}.
\end{equation}

	\item \begin{equation}\label{eq: recurrence}
	p_{k,n}^{(U)}=\begin{dcases}
	\frac{1}{n} \sum_{u=1}^n p_{k-1,u}^{(U)}, &k>1, \\
	\frac{1}{n}, &k=1,
	\end{dcases}
	\end{equation}
	and hence, for every $k>1$ one has
	\begin{equation}
	p_{k,n}^{(U)}=\frac{1}{n} \sum_{u\in\mathcal{U}_{k,n}} \frac{1}{u_1 u_2 ... u_{k-1}}
	\label{eq:sum_u_k_formula}
	\end{equation}
	where
	\begin{equation}
	\label{eq: P(S)}
	\mathcal{U}_{k,n}\equiv\left\{u=(u_1,\ldots,u_{k-1})\in\mathbb{Z}^{k-1}\ ;\ 1\leq u_1\leq u_2\leq\ldots\leq u_{k-1}\leq n\right\}.
	\end{equation}
\end{enumerate}
Furthermore, it is well known (see, e.g., \cite{barndorff1966distribution}) that for every fixed $k$, 
\begin{equation}
p_{k,n}^{(U)}\sim\frac{\log^{k-1}(n)}{n (k-1)!}\ \ \text{as}\ \ n\to\infty.
\label{eq:continuous_fixed_k_asymptotics}
\end{equation}

