\label{proposition: basic lemma}
	 Let $\left\{X_{ij};i,j\geq1\right\}$ be iid random variables with a distribution function $F$ for which $\gamma\equiv\gamma_F$ as defined in \eqref{eq:gamma_def}. In addition, let $G_2,G_3,\ldots$ be an iid sequence of geometric random variables with success probability $\alpha\in(0,1)$. 
	For every $n\geq1$, denote $M_n\equiv M_n^{(\alpha)}\equiv \underset{2\leq i\leq n}{\max} G_i$, and assume that $\left\{G_i ; i\geq2\right\}$ and $\left\{X_{ij};i,j\geq1\right\}$ are independent. 

	Then, for every $\alpha\in(0,1)\setminus\{1-e^{-\gamma}\}$, the random variable
	\begin{equation}
	 N_\alpha\equiv1+\begin{cases} 
      \sup\left\{n\geq1;M_n>M_n^1\right\}\vee0 & 1-\alpha<e^{-\gamma} \\
     \sup\left\{n\geq1;M_n<M_n^1\right\}\vee0 & 1-\alpha>e^{-\gamma} 
   \end{cases}   
	\end{equation}
	is $P$-a.s. finite.

For every $k\geq1$ denote 
\begin{equation}\label{eq: tau def}
\tau_k^1\equiv\min\left\{i\geq2;M_i^1\geq k\right\} , \ \ \tau_k \equiv \min\left\{i\geq2;M_i \geq k\right\}.
\end{equation}
Conditioned on $X_1\equiv\left(X_{1j}\right)_{j=1}^\infty$, the events
\begin{equation}
\left\{X_1^k\preceq X_i^k\right\} , \ \ i\geq2
\end{equation}
are independent. Therefore, the random variables $\tau_k^1$ and $\tau_k$ are conditionally independent given $X_1$, such that (notice that the index $i$ in \eqref{eq: tau def} is not less than 2)
\begin{equation}
\tau_k^1 | X_1-1 \sim\text{Geo}\left(\prod_{j=1}^k S(X_{1j})\right)
\end{equation}
and
\begin{equation}
\tau_k-1 \sim \text{Geo}\left(\left(1-\alpha\right)^k\right).
\end{equation} 
In addition, as explained in Section \ref{sec: gamma},
$S\left(X_{11}\right),S\left(X_{12}\right),\ldots$ are iid random variables and $-E \log S(X_{11})=\gamma\in(0,1]$. Therefore, by the strong law of large numbers
\begin{equation}\label{eq: SLLN}
L_k\equiv\frac{1}{k}\sum_{j=1}^k\left[-\log S(X_{1j})\right]\xrightarrow{k\to\infty}\gamma , \ \ P\text{-a.s.}
\end{equation}
and it follows that $e^{L_k} \xrightarrow{k\to\infty} e^\gamma$, $P$-a.s. and $e^{-kL_k}\xrightarrow{k\to\infty}0$, $P$-a.s.

Consider the case where $1-\alpha<e^{-\gamma}$. Then, \eqref{eq: SLLN} implies that there exists a $P$-a.s. finite random variable $K_\alpha$ which is uniquely determined by $X_1$ such that for every $k>K_\alpha$
\begin{equation}
(1-\alpha) e^{L_k} \leq \frac{1+(1-\alpha) e^\gamma}{2} \equiv \zeta_\alpha 
\end{equation}
such that $\zeta_\alpha<1$.
In addition, $e^{-k L_k} \leq 1$ for every $k \geq 1$. Therefore, by a well-known result about a minimum of two independent geometric random variables, deduce that

\begin{align}
\sum_{k=K_\alpha}^\infty P\left(\tau_k \leq \tau_k^1\big|X_1\right)&=\sum_{k=K_\alpha}^\infty P\left(\tau_k-1 \leq \tau_k^1-1\big|X_1\right)\\
&=\sum_{k=K_\alpha}^\infty\frac{(1-\alpha)^k}{(1-\alpha)^k+e^{-k L_k}-(1-\alpha)^k e^{-k L_k}} \nonumber\\
& \leq \sum_{k=K_\alpha}^\infty \left[(1-\alpha)e^{L_k}\right]^k 
\nonumber\\
&\leq\sum_{k=K_\alpha}^\infty\zeta_\alpha^k<\infty\nonumber.
\end{align}
Thus, the Lemma of Borel-Cantelli implies that
\begin{equation}
P\left(\tau_k \leq \tau_k^1\ , \ \text{i.o}\ \big| X_1\right)=0 , \ \ P\text{-a.s.}
\end{equation}
and hence 
\begin{equation}
P\left(\tau_k \leq\tau_k^1\ , \ \text{i.o}\ \right)=E\left[P\left(\tau_k \leq \tau_k^1\ , \ \text{i.o}\ \big| X_1\right)\right]=0.
\end{equation}
Therefore, $P(M_n > M_n^1 \, \ \text{i.o}) = 0$,
which yields the required result when $1-\alpha<e^{-\gamma}$. 


Assume that $1-\alpha>e^{-\gamma}$.
Then, applying similar arguments to those that appear above yields the existence of a P-a.s. finite random variable $K_{\alpha}$ such that for any $k>K_\alpha$:
